// Một Promise đại diện cho kết quả TƯƠNG LAI
const wait = (ms, value) =>
  new Promise((resolve) => setTimeout(() => resolve(value), ms));

wait(100, "xong!")
  .then((v) => {
    console.log(v);
    return v.toUpperCase();         // giá trị trả về chuyển sang .then kế tiếp
  })
  .then((v) => console.log(v))
  .catch((err) => console.log("lỗi", err))
  .finally(() => console.log("kết thúc"));

Promise.reject(new Error("hỏng")).catch((e) => console.log(e.message));

