solution.code:
const wait = (ms, value) =>
  new Promise((resolve) => setTimeout(() => resolve(value), ms));

const failing = Promise.reject(new Error("x"));

Promise.all([wait(50, "a"), wait(100, "b"), wait(30, "c")])
  .then((results) => console.log(results.join("")));

failing.catch((e) => console.log(e.message));
